exploreUrl:
@js:
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});

url = (theme) => `@js:
"https://api.mangacopy.com/api/v3/comics?ordering=-datetime_updated&limit=21&offset={{(page-1)*21}}&free_type=1&theme=${theme}&_update=true"` 

push("全部题材", "", 1)
tagUrl = 'https://api.mangacopy.com/api/v3/theme/comic/count?free_type=1&limit=500&offset=0&_update=true' 
let $ = JSON.parse(java.ajax(tagUrl)).results.list
$.forEach(($) => {
  push($.name, url($.path_word), 0.25)
})

JSON.stringify(sort)
